# Grammar topics (by lesson title) + hand-written per-item extras for A1/A2.
# topic: id -> (title, explanation, common mistakes for Spanish speakers)
T = {
 "saludos": ("Saludos", "«Bon dia» se usa hasta el mediodía; luego «bona vesprada» y por la noche «bona nit» (sirve para saludar y despedirse). «Adéu» vale para despedirse siempre.", "Decir «bones tardes» o «bon dies»: en valenciano es «bona vesprada» y «bon dia» en singular."),
 "presentarse": ("Presentarse", "Para el nombre se usa el verbo «dir-se»: em dic, et dius, es diu. «Soc de…» indica origen y «visc a…» dónde vives (con ciudades se usa «a»).", "Calcar «me llamo» → «em crido»: es incorrecto, se dice «em dic». «Visc en València» → mejor «visc a València»."),
 "cortesia": ("Cortesía", "«Per favor», «gràcies», «de res» y «perdó» funcionan como en castellano. «No passa res» = no pasa nada.", "«Gracies» sin acento: se escribe «gràcies» (a abierta). «De nada» → «de res», no «de nada»."),
 "estats": ("Cómo estás", "Con estados de ánimo o salud se usa «estar»: estic bé, estic cansat. El adjetivo concuerda: cansat/cansada, content/contenta.", "Usar «soc cansat»: con estados es «estic cansat»."),
 "numeros": ("Números", "1 = u (al contar) o un/una (delante de nombre). 2 = dos (masc.) / dues (fem.). Formas valencianas: huit, dèsset, díhuit, dènou, huitanta (también vuit, disset, divuit, dinou, vuitanta). Las decenas se unen con guion: vint-i-u, trenta-dos.", "Decir «dos germanes»: en femenino es «dues germanes». Olvidar los guiones: «trenta-dos», «vint-i-tres»."),
 "familia": ("La familia y los posesivos", "Los posesivos llevan artículo: el meu pare, la meua mare, els meus germans, les meues ties. Formas valencianas: meu/meua, teu/teua, seu/seua.", "Omitir el artículo: «meu pare» → «el meu pare». Usar «meva» (forma del catalán central): en valenciano es «meua»."),
 "descripcio": ("Describir personas", "Para rasgos permanentes se usa «ser»: és alt, és simpàtica. El femenino suele añadir -a: alt/alta, ros/rossa, moré/morena.", "Olvidar la doble s en «rossa» (femenino de ros)."),
 "menjar": ("Comida", "Vocabulario muy valenciano: creïlla (patata), tomaca (tomate), esmorzar (almorzar a media mañana o desayunar), dinar (comida del mediodía), sopar (cenar). «M'agrada» funciona como «me gusta».", "«Tomate» → «tomaca» (también «tomata»). «Vino tinto» es «vi negre»."),
 "bar": ("En el bar", "«Per a mi…» para pedir, «el compte» para la cuenta. «Un café amb llet», «un tallat» (cortado), «un entrepà» (bocadillo).", "«La cuenta» → «el compte» (masculino)."),
 "dies": ("Días de la semana", "Los días son masculinos y sin artículo cuando hablas de un día concreto: «dilluns treballe» = el lunes trabajo. Con artículo indica hábito: «els dilluns» = los lunes.", "Poner artículo siempre: «el dilluns treballe» suena a calco; basta «dilluns treballe»."),
 "quan": ("¿Cuándo?", "Hui (hoy), demà (mañana), ahir (ayer), ara (ahora). Partes del día: matí, vesprada, nit. «Al matí» = por la mañana.", "Confundir «demà» (mañana, día siguiente) con «matí» (la mañana, parte del día)."),
 "hora": ("La hora", "«Quina hora és?» → «És la una», «Són les dues». Fracciones: i quart, i mitja, menys quart. (Existe también el sistema tradicional de «quarts»: «dos quarts de quatre» = las tres y media).", "Decir «són les una»: con la una es singular, «és la una»."),
 "mesos": ("Meses y estaciones", "Los meses van en minúscula: gener, febrer, març… Se dice «al març» (en marzo). Estaciones: primavera, estiu, tardor, hivern. Tiempo: fa calor, fa fred, plou.", "«Hace calor» con «hacer» se mantiene: «fa calor» (no «està calor»)."),
 "colors": ("Colores", "Los colores concuerdan en género: roig/roja, groc/groga, blanc/blanca, negre/negra. Algunos no varían: blau (fem. blava), gris, rosa, marró.", "Femenino de «roig» es «roja» y el de «groc» es «groga»."),
 "roba": ("Ropa y compras", "«Portar» = llevar puesto: porte una camisa. «Quant costa?» para preguntar el precio. «Car/barat» = caro/barato.", "Usar «llevar» para la ropa: en valenciano «llevar» significa quitar; para la ropa que llevas es «portar»."),
 "casa": ("La casa", "Para situar algo se usa «ser»: la llet és a la nevera, el bany és a dalt. Imperativos útiles: obri (abre), tanca (cierra).", "Decir «la llet està a la nevera»: es coloquial; la forma normativa es «és a la nevera»."),
 "tasques": ("Tareas de casa", "Verbos muy valencianos: escurar (fregar los platos), agranar (barrer), tirar el fem (sacar la basura), netejar (limpiar).", "«Fregar» en valenciano es frotar/fregar el suelo; los platos se «escuren»."),
 "present": ("Presente: primera persona en -e", "En valenciano la 1.ª persona del presente de los verbos en -ar acaba en -e: parle, treballe, estudie, menge. Otros verbos: escric, llig, dorm, bec.", "Usar la terminación del catalán central -o («parlo») o -i («parli»): en valenciano es «parle»."),
 "irregulars": ("Verbos irregulares frecuentes", "vaig (anar), isc (eixir), faig (fer), puc (poder), vull (voler), sé (saber), vinc (vindre), conec (conéixer), dic (dir).", "Confundir «vaig» (voy) con el pasado perifrástico «vaig anar» (fui)."),
 "preguntes": ("Preguntas", "què (qué), qui (quién), on (dónde), quan (cuándo), per què (por qué, separado y con acento), com (cómo), quant/quants (cuánto/s), quin/quina (cuál, qué + nombre).", "Escribir «perquè» en preguntas: la pregunta es «per què?» (separado); «perquè» es la respuesta (porque)."),
 "conjugacio": ("Conjugar verbos en -ar", "parlar: jo parle, tu parles, ell/ella parla, nosaltres parlem, vosaltres parleu, ells/elles parlen.", "Olvidar la -eu de vosotros: «vosaltres parleu»."),
 "perifrastic": ("Pasado perifrástico", "El pasado más usado se forma con anar + infinitivo: vaig anar (fui), vas parlar (hablaste), va menjar (comió), vam, vau, van + infinitivo.", "Interpretarlo como futuro («voy a ir»): «vaig anar» es pasado. Para el futuro se usa «aniré»."),
 "marcadors": ("Marcadores de pasado", "anit (anoche), ahir, abans-d'ahir, la setmana passada, l'any passat, fa dos dies.", "Escribir «abans d'ahir» sin guiones: la forma normativa es «abans-d'ahir»."),
 "futur": ("Futuro", "Infinitivo + é, às, à, em, eu, an: parlaré, parlaràs, parlarà… Irregulares: faré, tindré, vindré, podré, eixiré.", "Olvidar el acento: parlaré, parlarà."),
 "condicional": ("Condicional", "Infinitivo + ia: parlaria, voldria, podria, m'agradaria. «Hauries de» = deberías.", "Decir «deuries»: en valenciano se usa «hauries de» o «hauries de + infinitivo»."),
 "plans": ("Planes y condiciones", "Si + presente → futuro: si plou, em quedaré a casa. Potser (quizás), segurament (seguramente).", "Poner futuro tras «si»: «si plourà» es incorrecto; «si plou»."),
 "opinio": ("Opinar", "Crec que, pense que, em sembla que + indicativo. Estic d'acord / no estic d'acord. Tens raó.", "Decir «tens raó» con «tindre»: correcto. Evitar «tens la raó»."),
 "connectors": ("Conectores básicos", "però (pero), perquè (porque), així que (así que), a més (además), també (también), tampoc (tampoco).", "Confundir «perquè» (porque) con «per què» (por qué)."),
 "adverbis": ("Adverbios de tiempo", "encara (todavía), ja (ya), mai (nunca), sempre (siempre), sovint (a menudo), de vegades (a veces). Con «mai» se suele usar «no»: mai no he estat.", "Traducir «todavía» por «todavia»: es «encara»."),
 "viatges": ("Viajes", "bitllet, estació, andana, eixida, arribada, retard. «Porta retard» = lleva retraso.", "«Salida» es «eixida» (de eixir)."),
 "direccions": ("Direcciones", "a la dreta, a l'esquerra, tot recte, a prop, lluny. Para situar se usa «ser»: l'hotel és a prop.", "Usar «està a prop» por calco: la forma recomendada es «és a prop»."),
 "treball": ("Trabajo", "feina (trabajo, empleo), cap (jefe), sou (sueldo), atur (paro), contracte.", "«Trabajo» como tarea concreta suele ser «feina»; «treball» también existe."),
 "salut": ("Salud: fer mal", "Para el dolor se usa «fer mal»: em fa mal el cap (me duele la cabeza), em fan mal els peus.", "Calcar «em dol el cap»: lo habitual es «em fa mal el cap»."),
 "pf-directe": ("Pronombres débiles: complemento directo", "el (lo), la, els (los), les (las). Delante de vocal: l'. El llibre → el tinc. La pel·lícula → l'he vista (el participio concuerda con la).", "Usar «li» como complemento directo («li veig»): con persona masculina es «el veig»."),
 "pf-indirecte": ("Pronombres débiles: complemento indirecto", "li (le), els (les). Combinado con «ho»: li ho done (se lo doy). em, et, ens, us.", "Traducir «se lo doy» por «se'l done»: es «li ho done» o «l'hi done»."),
 "pf-en-hi": ("En e hi", "«En» sustituye a algo introducido por «de» o a una cantidad: en vull dos. «Hi» sustituye a un lugar: hi vaig. «Hi ha» = hay.", "Omitir «en» con cantidades: «vull dos» → «en vull dos»."),
 "connectors-av": ("Conectores avanzados", "tanmateix (sin embargo), per tant (por lo tanto), malgrat (a pesar de), sinó (sino), és a dir, en canvi, de fet.", "Escribir «sino» sin acento: en valenciano es «sinó»."),
 "frases-fetes": ("Frases hechas", "Expresiones idiomáticas: no se traducen palabra por palabra. Anar de bòlit (ir muy liado), ploure a bots i barrals (llover a cántaros).", "Traducir literalmente «llover a cántaros»."),
 "refranys": ("Refranes", "Los refranes son fijos: qui matina fa farina, a poc a poc s'arriba lluny.", "Cambiar palabras del refrán."),
 "subj-present": ("Subjuntivo presente", "Tras verbos de deseo o posibilidad: vull que vingues, espere que estigues bé, és possible que ploga. En valenciano: -e/-es/-e (parle, parles) en verbos en -ar; -a en otros (vinga, siga).", "Usar indicativo: «vull que vens» → «vull que vingues»."),
 "subj-imperfet": ("Subjuntivo imperfecto", "En valenciano: -ra: si tinguera, si poguera, si fóra. Con «si» + imperfecto de subjuntivo → condicional.", "Mezclar «si tindria»: tras «si» va subjuntivo: «si tinguera»."),
 "indic-subj": ("¿Indicativo o subjuntivo?", "Crec que + indicativo (crec que ve); no crec que + subjuntivo (no crec que vinga). Quan + subjuntivo para el futuro: quan arribes.", "«Quan arribaràs» → «quan arribes»."),
 "formal": ("Registro formal", "Vosté (usted) + 3.ª persona. Cartas: Benvolgut senyor / Benvolguda senyora, Atentament.", "Usar «Estimat senyor» en cartas formales: lo habitual es «Benvolgut senyor»."),
 "formes-val": ("Formas valencianas normativas", "La AVL admite formas valencianas como hui, eixir, xicotet, espill, este/eixe, servici, vore, tindre, vindre y la 1.ª persona en -e (parle).", "Creer que estas formas son «vulgarismos»: son normativas."),
 "cultura": ("Cultura valenciana", "Falles: plantà, mascletà, ofrena, cremà. Gastronomía: orxata amb fartons, all i pebre. Literatura: Ausiàs March, Tirant lo Blanc, Estellés, Fuster.", ""),
 "falsos-amics": ("Falsos amigos", "cama = pierna; llit = cama; constipat = resfriado; tasca = tarea; llevar = quitar; portar = llevar; escurar = fregar platos; acostar = acercar.", "Interpretar estas palabras con su sentido castellano."),
 "quantificadors": ("Cuantificadores", "prou (bastante), massa (demasiado), gens (nada de, en negativas), res (nada), gaire (mucho, en negativas), cap (ningún).", "«No tinc res de son» → «no tinc gens de son»."),
 "pf-comb": ("Combinaciones de pronombres", "te'l done (te lo doy), me la deixes? (¿me la dejas?), li'n done dos, l'hi porte, els ho explique.", "«Se'l done» por «se lo doy»: es «l'hi done» o «li'l done»."),
 "imperatiu": ("Imperativo con pronombres", "Los pronombres van detrás y con guion: dona-li-ho, digues-m'ho, fes-ho, anem-nos-en.", "Poner el pronombre delante en imperativo afirmativo."),
 "registre-cult": ("Registro culto", "àdhuc (incluso), llevat de (excepto), així mateix (asimismo), tot i que (aunque), nogensmenys (no obstante).", ""),
 "administracio": ("Lenguaje administrativo", "instància, expedient, termini (plazo), tràmit, registre, al·legació.", "«Plazo» → «termini», no «plaç»."),
 "llengua": ("La lengua", "La AVL (creada en 1998) es la institución normativa. Las Normes de Castelló (1932) fijaron la ortografía.", ""),
 "alfabet": ("El alfabeto", "Las letras tienen nombre femenino: la a, la be, la ce… Formas valencianas normativas (AVL): efe, ele, eme, ene, erre, esse (también fe, el, em, en, er, es). La b y la v se pueden llamar «be alta» y «ve baixa».", "Pronunciar la v como b en todas partes: en buena parte del valenciano la v suena labiodental [v]."),
 "lletrejar": ("Deletrear", "Para deletrear se dice cada letra: «hola: hac, o, ele, a». Signos útiles: ela geminada (l·l), ce trencada (ç), apòstrof ('), guionet (-), dièresi (ï, ü).", "Olvidar el punto volado de la ela geminada: «col·legi», no «colegi»."),
 "accents": ("Los acentos", "El valenciano tiene dos acentos: obert (à, è, ò) y tancat (é, í, ó, ú). Llevan acento las agudas acabadas en vocal, -as, -es, -is, -os, -us, -en, -in: també, cançó, café. En valenciano «e» tónica cerrada se escribe é: café, francés, anglés. Desde 2018 la AVL solo mantiene 15 acentos diacríticos (bé, déu, és, mà, més, món, pèl, què, sé, sí, sòl, té, ús, vós…): «soc» ya no lleva acento.", "Escribir «sóc» o «dóna»: la AVL los suprimió en 2018; hoy es «soc» y «dona»."),
 "dades": ("Datos personales", "Edad con «tindre»: tinc trenta anys. Dirección: carrer, número, pis, porta, codi postal. Estado civil con «estar» o «ser»: estic casada / soc solter.", "Calcar «tengo 30 años» está bien; lo que no se dice es «soc 30 anys»."),
 "nacionalitats": ("Países y nacionalidades", "Los gentilicios concuerdan: francés/francesa, anglés/anglesa, alemany/alemanya, italià/italiana. En valenciano la e tónica de -és es cerrada (francés, anglés); también se acepta francès, anglès.", "Escribirlos con mayúscula: en valenciano los gentilicios van en minúscula (és francesa)."),
 "articles": ("Artículos y apóstrofo", "Artículos: el, la, els, les; un, una, uns, unes. Delante de vocal o h se apostrofa: l'home, l'aigua, l'amiga. «La» no se apostrofa ante i/u átonas (la illa, la universitat) ni ante la negación «a-» (la anormalitat).", "Escribir «l'illa» o «l'universitat»: la forma correcta es «la illa», «la universitat»."),
 "contraccions": ("Contracciones", "a + el = al, a + els = als, de + el = del, de + els = dels, per + el = pel, per + els = pels. Con «la» o ante vocal no se contrae: a la, de l'home.", "Contraer con femenino («dela») o ante vocal («del home»): es «de la» y «de l'home»."),
 "possessius": ("Posesivos", "Con artículo: el meu, la meua, els meus, les meues; el teu/la teua; el seu/la seua; el nostre/la nostra; el vostre/la vostra; el seu (de ells). Formas valencianas: meua, teua, seua.", "Omitir el artículo («meu pare»): lo normal es «el meu pare» (o «mon pare», más literario)."),
 "femeni-plural": ("Femenino y plural", "Femenino: suele añadir -a (xic/xica, nou/nova). Plural: -s (llibre/llibres); -a → -es (casa/cases); tras -s, -x, -ç → -os (peix/peixos). Cambios: -ca → -ques, -ga → -gues, -ja → -ges.", "Hacer «cases» como «casas»: el plural de -a es -es."),
 "concordanca": ("Concordancia", "Nombre y adjetivo concuerdan en género y número: un cotxe blanc, una casa blanca, uns cotxes blancs, unes cases blanques.", "Olvidar el cambio ortográfico: «blancas» → «blanques», «bonicas» → «boniques»."),
 "mercat": ("Mercado y horno", "Cantidades con «de»: un quilo de, mig quilo de, una dotzena d'ous. En Valencia la panadería es «el forn». Tiendas en -eria: carnisseria, peixateria, pastisseria.", "Decir «medio quilo»: es «mig quilo»."),
 "aficions": ("Aficiones y deportes", "«M'agrada» + singular o infinitivo, «m'agraden» + plural. «M'encanta» para gustos fuertes; «no m'agrada gens» = no me gusta nada. Deportes con «fer» (fer esport) o «jugar a» (jugar a futbol).", "Decir «m'agrada les pel·lícules»: con plural es «m'agraden»."),
 "frequencia": ("Frecuencia", "sempre, sovint, de vegades, mai, cada dia, una vegada / dues vegades per setmana. «Mai» va solo o con «no»: mai faig esport / no faig mai esport.", "Usar «vez» → en valenciano es «vegada»."),
 "imperatiu-receptes": ("Imperativo en recetas", "Tú afirmativo = 3.ª persona del presente: talla, pela, posa, remena. Formas valencianas: afig (afegir), bull (bullir), fregix (fregir), servix (servir). Negativo con subjuntivo: no cremes, no talles.", "Usar el infinitivo para mandar («tallar la ceba»): en una receta oral se usa el imperativo «talla la ceba»."),
 "haver-de": ("Obligación: haver de", "haver de + infinitivo = tener que: he de, has de, ha de, hem de, heu de, han de. Impersonal: s'ha de / cal + infinitivo. «No cal» = no hace falta.", "Calcar «tindre que»: es incorrecto; se dice «haver de»."),
 "participi": ("El participio", "Regular: -ar → -at (parlat), -er/-re → -ut (begut, perdut), -ir → -it (dormit). Irregulares frecuentes: fet, vist, dit, escrit, obert, pres, mort.", "Decir «hecho» → «fet», no «fit»; «abierto» → «obert»."),
 "perfet": ("Pretérito perfecto", "haver (he, has, ha, hem, heu, han) + participio: he menjat, has fet, ha dit. Se usa para un tiempo que no ha terminado (hui, este matí, esta setmana) o sin fecha (alguna vegada, ja, encara no).", "Poner algo entre «he» y el participio como en inglés: se dice «ja he menjat» / «encara no he menjat»."),
 "perfet-vs-perifrastic": ("He menjat o vaig menjar", "Tiempo terminado (ahir, l'any passat) → vaig + infinitivo: ahir vaig menjar paella. Tiempo que incluye el ahora (hui, este matí) → he + participio: hui he menjat paella.", "Usar «vaig menjar» con «hui»: lo normal es «hui he menjat»."),
 "mitjans": ("Noticias y medios", "diari, notícia, ràdio, televisió, xarxes socials. Para contar una noticia: «segons…», «hi ha hagut…», perfecto para hechos recientes.", "Decir «periòdic» es correcto, pero en valenciano es muy habitual «diari»."),
 "eines": ("Herramientas y aparatos", "«Per a què servix?» (forma valenciana de servir). Verbos: encendre (encén), apagar, funcionar, arreglar, penjar.", "Decir «encender» → «encendre»; el imperativo es «encén»."),
 "cotxe": ("Coche y bici", "conduir, aparcar, el carnet de conduir, el taller, una avaria. «Portar el cotxe al taller».", "Usar «llevar» por «portar»: «llevar» en valenciano es quitar."),
 "reclamacio": ("Reclamaciones", "«Vull fer una reclamació», «demanar el full de reclamacions», «tornar els diners», «canviar-lo», «té garantia».", "Decir «devolver el dinero» → «tornar els diners»."),
 "medi": ("Medio ambiente", "reciclar, reutilitzar, reduir; contenidor de vidre, paper, plàstic i envasos. «Cal» / «hem de» para proponer.", "Escribir «plastic» sin acento: es «plàstic»."),
}
